          endpoint,
          attempt,
          reason,
          reason === 'timeout'
            ? `Request timed out after ${timeoutMs}ms.`
            : reason === 'aborted'
              ? 'Request was aborted.'
              : error instanceof Error
                ? error.message
                : 'Network request failed.',
        );

